3	const { Router } = require('express');
4	const fs = require('fs');
5	const path = require('path');
6	const os = require('os');
7	const crypto = require('crypto');
8	const { spawn } = require('child_process');
9	const { rateLimit } = require('../middleware/rateLimit');
10	const { loadConfig } = require('../lib/config');
11	const { discoverProjects } = require('../lib/discovery');
12	const db = require('../db');
13	
14	const router = Router();
15	
16	const HOME = os.homedir();
17	const CLAUDE_DIR = path.join(HOME, '.claude');
18	const TEMPLATES_DIR = path.join(CLAUDE_DIR, 'templates');
19	const TRAINING_DIR = path.join(CLAUDE_DIR, 'training');
20	
21	function loadPlaygroundHistory() { return db.loadPlaygroundHistory(); }
22	function savePlaygroundHistory(list) { try { db.savePlaygroundHistory(list); } catch (err) { console.error('[savePlaygroundHistory] DB write failed:', err.message); throw err; } }
23	
24	function genId() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 7); }
25	
26	function logAgentRun(entry) {
27	  const estimateTokens = (text) => Math.ceil((text || '').length / 4);
28	  const estimateCost = (i, o) => (i * 3 + o * 15) / 1_000_000;
29	  const inputTokens = estimateTokens(entry.prompt || '');
30	  const outputTokens = estimateTokens(entry.output || '');
31	  const run = {
32	    id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7),
33	    agentName: entry.agentName || 'unknown',
34	    prompt: (entry.prompt || '').slice(0, 200),
35	    source: entry.source || 'unknown',
36	    timestamp: new Date().toISOString(),
37	    duration: entry.duration || 0,
38	    status: entry.status || 'success',
39	    promptChars: (entry.prompt || '').length,
40	    outputChars: (entry.output || '').length,
41	    estimatedTokens: inputTokens + outputTokens,
42	    estimatedCost: estimateCost(inputTokens, outputTokens),
43	    error: entry.error || null,
44	    metadata: entry.metadata || {},
45	  };
46	  try { db.insertAgentRun(run); } catch (err) { console.error('[logAgentRun] DB insert failed:', err.message); }
47	  return run;
48	}
49	
50	// POST /api/playground/run
51	router.post('/playground/run', rateLimit('heavy'), (req, res) => {
52	  const { agentName, prompt: userPrompt, customInstructions, timeoutMs } = req.body;
53	  if (!userPrompt) return res.status(400).json({ error: 'Prompt is required' });
54	
55	  const reqId = crypto.randomUUID();
56	  res.setTimeout(0);
57	  res.setHeader('Content-Type', 'text/event-stream');
58	  res.setHeader('Cache-Control', 'no-cache');
59	  res.setHeader('Connection', 'keep-alive');
60	  res.setHeader('X-Accel-Buffering', 'no');
61	  res.flushHeaders();
62	
63	  let ended = false;
64	  let streamDead = false;
65	
66	  const safeWrite = (raw) => {
67	    if (ended || streamDead) return true;
68	    try {
69	      return res.write(raw);
70	    } catch (err) {
71	      streamDead = true;
72	      console.error('[playground] sse write failed', { agent: agentName || 'custom', reqId, code: err.code, msg: err.message });
73	      try { if (typeof hardKill === 'function') hardKill('stream_dead'); } catch { /* proc not ready yet */ }
74	      return false;
75	    }
76	  };
77	  const send = (data) => safeWrite(`data: ${JSON.stringify(data)}\n\n`);
78	  const sendComment = (text) => safeWrite(`: ${text}\n\n`);
79	
80	  let instructions = '';
81	  if (agentName) {
82	    const agentContentMap = {};
83	    const globalAgentsDir = path.join(CLAUDE_DIR, 'agents');
84	    if (fs.existsSync(globalAgentsDir)) {
85	      for (const file of fs.readdirSync(globalAgentsDir).filter(f => f.endsWith('.md'))) {
86	        const content = fs.readFileSync(path.join(globalAgentsDir, file), 'utf-8');
87	        const nameMatch = content.match(/^name:\s*(.+)$/m);
88	        const key = nameMatch ? nameMatch[1].trim() : file.replace('.md', '');
89	        agentContentMap[key] = content;
90	        agentContentMap[file.replace('.md', '')] = content;
91	      }
92	    }
93	    const config = loadConfig();
94	    const projects = discoverProjects(config.projectDirs);
95	    for (const p of projects) {
96	      for (const a of (p.agents || [])) {
97	        agentContentMap[a.name] = a.body || a.raw;
98	        agentContentMap[a.filename] = a.body || a.raw;
99	      }
100	    }
101	    instructions = agentContentMap[agentName] || '';
102	
103	    if (!instructions) {
104	      send({ type: 'error', error: `Agent "${agentName}" not found in global or project agents` });
105	      logAgentRun({ agentName: agentName || 'custom', prompt: userPrompt, output: '', source: req.body.source || 'playground', duration: 0, status: 'error', error: 'agent_not_found', metadata: { reqId } });
106	      try { res.end(); } catch {}
107	      return;
108	    }
109	
110	    try {
111	      const matter = require('gray-matter');
112	      const agentPath = path.join(CLAUDE_DIR, 'agents', agentName + '.md');
113	      if (fs.existsSync(agentPath)) {
114	        const { data: agentMeta } = matter(fs.readFileSync(agentPath, 'utf-8'));
115	        if (agentMeta.output_template) {
116	          const tmplPath = path.join(TEMPLATES_DIR, agentMeta.output_template + '.md');
117	          if (fs.existsSync(tmplPath)) {
118	            const { content: tmplBody } = matter(fs.readFileSync(tmplPath, 'utf-8'));
119	            instructions += '\n\n## OUTPUT FORMAT (MANDATORY)\nYou MUST structure your response exactly as follows. Do not deviate from this format.\n\n' + tmplBody.trim();
120	          }
121	        }
122	      }
123	    } catch (err) {
124	      console.warn('[playground] output_template load failed', { agent: agentName, reqId, msg: err.message });
125	      send({ type: 'warning', scope: 'instructions', message: `output_template load failed: ${err.message}` });
126	    }
127	
128	    try {
129	      const agentKey = agentName.replace(/\s.*$/, '').toLowerCase();
130	      const trainingFiles = [agentName, agentKey].map(n => path.join(TRAINING_DIR, n + '.json'));
131	      for (const tf of trainingFiles) {
132	        if (fs.existsSync(tf)) {
133	          const corrections = JSON.parse(fs.readFileSync(tf, 'utf-8')).filter(c => c.status === 'active');
134	          if (corrections.length > 0) {
135	            instructions += '\n\n## TRAINING CORRECTIONS (Follow these strictly)\n' +
136	              corrections.map((c, i) => `${i + 1}. [${c.timestamp.split('T')[0]}] ${c.correction}`).join('\n');
137	          }
138	          break;
139	        }
140	      }
141	    } catch (err) {
142	      console.warn('[playground] training corrections load failed', { agent: agentName, reqId, msg: err.message });
143	      send({ type: 'warning', scope: 'instructions', message: `training corrections load failed: ${err.message}` });
144	    }
145	  }
146	
147	  if (customInstructions) {
148	    instructions = customInstructions;
149	  }
150	
151	  let fullPrompt = '';
152	  if (instructions) {
153	    fullPrompt = `${instructions}\n\n---\n\n## Task:\n${userPrompt}\n\n---\n\nIMPORTANT: Produce the actual deliverable directly. Do NOT write meta-commentary. Output only the finished work product.`;
154	  } else {
155	    fullPrompt = userPrompt;
156	  }
157	
158	  const timeout = Math.min(timeoutMs ?? 120000, 600000);
159	  const IDLE_MS = Number(process.env.PLAYGROUND_IDLE_MS) || 90000;
160	  const HEARTBEAT_MS = Number(process.env.PLAYGROUND_HEARTBEAT_MS) || 15000;
161	  const claudePath = process.env.CLAUDE_PATH || 'claude';
162	  const childEnv = { ...process.env, HOME: os.homedir() };
163	  delete childEnv.CLAUDECODE;
164	  delete childEnv.CLAUDE_CODE_ENTRYPOINT;
165	  delete childEnv.CLAUDE_CODE_ENABLE_SDK_FILE_CHECKPOINTING;
166	  delete childEnv.CLAUDE_AGENT_SDK_VERSION;
167	  const proc = spawn(claudePath, ['-p'], { env: childEnv, detached: true });
168	  let fullOutput = '';
169	  let lastActivityAt = Date.now();
170	  let killReason = null;
171	  let sigkillTimer = null;
172	
173	  function hardKill(reason) {
174	    if (killReason) return;
175	    killReason = reason;
176	    const killSignal = (sig) => {
177	      try {
178	        if (proc.pid) process.kill(-proc.pid, sig);
179	      } catch {
180	        try { proc.kill(sig); } catch { /* already dead */ }
181	      }
182	    };
183	    killSignal('SIGTERM');
184	    sigkillTimer = setTimeout(() => killSignal('SIGKILL'), 5000);
185	    if (sigkillTimer && typeof sigkillTimer.unref === 'function') sigkillTimer.unref();
186	  }
187	
188	  const touchActivity = () => { lastActivityAt = Date.now(); };
189	
190	  const timer = setTimeout(() => { hardKill('wall_timeout'); }, timeout);
191	
192	  const idleTimer = setInterval(() => {
193	    if (killReason) return;
194	    const idleFor = Date.now() - lastActivityAt;
195	    if (idleFor >= IDLE_MS) {
196	      send({ type: 'stalled', reason: 'no_output', idleMs: idleFor });
197	      hardKill('idle_timeout');
198	      clearInterval(idleTimer);
199	    }
200	  }, 5000);
201	  if (typeof idleTimer.unref === 'function') idleTimer.unref();
202	
203	  const heartbeatTimer = setInterval(() => sendComment('hb ' + Date.now()), HEARTBEAT_MS);
204	  if (typeof heartbeatTimer.unref === 'function') heartbeatTimer.unref();
205	
206	  const finish = () => {
207	    if (ended) return;
208	    ended = true;
209	    clearTimeout(timer);
210	    if (sigkillTimer) clearTimeout(sigkillTimer);
211	    clearInterval(idleTimer);
212	    clearInterval(heartbeatTimer);
213	    try { res.end(); } catch {}
214	  };
215	
216	  const playgroundStartTime = Date.now();
217	  send({ type: 'start', agent: agentName || 'custom' });
218	
219	  proc.stdout.on('data', (data) => {
220	    if (ended) return;
221	    touchActivity();
222	    if (streamDead) return;
223	    const chunk = data.toString();
224	    fullOutput += chunk;
225	    const ok = send({ type: 'chunk', content: chunk });
226	    if (ok === false) {
227	      proc.stdout.pause();
228	      res.once('drain', () => {
229	        if (!ended && !streamDead) proc.stdout.resume();
230	      });
231	    }
232	  });
233	
234	  proc.stderr.on('data', (data) => {
235	    if (ended) return;
236	    touchActivity();
237	    if (streamDead) return;
238	    const msg = data.toString().trim();
239	    if (msg) send({ type: 'activity', message: msg });
240	  });
241	  proc.stderr.on('error', (err) => {
242	    console.warn('[playground] stderr stream error', { agent: agentName || 'custom', reqId, code: err.code, msg: err.message });
243	  });
244	
245	  proc.on('close', (code) => {
246	    if (ended) { if (sigkillTimer) clearTimeout(sigkillTimer); return; }
247	    const runSource = req.body.source || 'playground';
248	    const duration = Date.now() - playgroundStartTime;
249	    const baseLog = {
250	      agentName: agentName || 'custom',
251	      prompt: userPrompt,
252	      source: runSource,
253	      duration,
254	      metadata: { reqId, exitCode: code, killReason },
255	    };
256	
257	    if (killReason === 'wall_timeout') {
258	      send({ type: 'error', error: `Timed out after ${timeout / 1000}s` });
259	      logAgentRun({ ...baseLog, output: fullOutput.trim(), status: 'error', error: `wall_timeout_${timeout / 1000}s` });
260	    } else if (killReason === 'idle_timeout') {
261	      send({ type: 'error', error: `Agent produced no output for ${Math.round(IDLE_MS / 1000)}s (idle timeout). Process killed.` });
262	      logAgentRun({ ...baseLog, output: fullOutput.trim(), status: 'error', error: `idle_timeout_${Math.round(IDLE_MS / 1000)}s` });
263	    } else if (killReason === 'stdin_error') {
264	      logAgentRun({ ...baseLog, output: fullOutput.trim(), status: 'error', error: 'stdin_error' });
265	    } else if (killReason === 'client_disconnect') {
266	      logAgentRun({ ...baseLog, output: fullOutput.trim(), status: 'cancelled', error: 'client_disconnect' });
267	    } else if (killReason === 'stream_dead') {
268	      logAgentRun({ ...baseLog, output: fullOutput.trim(), status: 'error', error: 'stream_dead' });
269	    } else if (code !== 0) {
270	      const partial = fullOutput.trim() ? ' after partial output' : '';
271	      send({ type: 'error', error: `claude exited with code ${code}${partial}` });
272	      logAgentRun({ ...baseLog, output: fullOutput.trim(), status: 'error', error: `exit_code_${code}` });
273	    } else if (code === 0 && !fullOutput.trim()) {
274	      send({ type: 'error', error: 'claude exited 0 but produced no output. This usually means the prompt was rejected, auth failed, or the CLI wrote to a path that was empty. Check CLAUDE_PATH and credentials.' });
275	      logAgentRun({ ...baseLog, output: '', status: 'error', error: 'empty_output' });
276	    } else {
277	      send({ type: 'done', output: fullOutput.trim(), exitCode: code, durationMs: duration });
278	      logAgentRun({ ...baseLog, output: fullOutput.trim(), status: 'success' });
279	    }
280	    finish();
281	  });
282	
283	  proc.on('error', (err) => {
284	    if (ended) return;
285	    send({ type: 'error', error: err.message });
286	    logAgentRun({
287	      agentName: agentName || 'custom',
288	      prompt: userPrompt,
289	      output: fullOutput.trim(),
290	      source: req.body.source || 'playground',
291	      duration: Date.now() - playgroundStartTime,
292	      status: 'error',
293	      error: `spawn_error: ${err.message}`,
294	      metadata: { reqId, killReason, code: err.code },
295	    });
296	    finish();
297	  });
298	
299	  let stdinErrorHandled = false;
300	  const handleStdinErr = (err) => {
301	    if (stdinErrorHandled || ended) return;
302	    stdinErrorHandled = true;
303	    console.error('[playground] stdin error', { agent: agentName || 'custom', reqId, code: err.code, msg: err.message });
304	    send({ type: 'error', error: `Failed to send prompt to claude (${err.code || 'write_error'}): ${err.message}` });
305	    hardKill('stdin_error');
306	  };
307	  proc.stdin.on('error', handleStdinErr);
308	
309	  const writeOk = proc.stdin.write(fullPrompt, 'utf8', (err) => {
310	    if (err) { handleStdinErr(err); return; }
311	  });
312	  if (writeOk) {
313	    try { proc.stdin.end(); } catch (err) { handleStdinErr(err); }
314	  } else {
315	    proc.stdin.once('drain', () => {
316	      try { proc.stdin.end(); } catch (err) { handleStdinErr(err); }
317	    });
318	  }
319	
320	  res.on('close', () => {
321	    if (!killReason) hardKill('client_disconnect');
322	  });
323	});
324	
325	// GET /api/playground/history
326	router.get('/playground/history', rateLimit('read'), (req, res) => {
327	  res.json(loadPlaygroundHistory());
328	});
329	
330	// POST /api/playground/history
331	router.post('/playground/history', rateLimit('write'), (req, res) => {
332	  const { id, agent, agentName, prompt, output, duration, status, timestamp } = req.body;
333	  if (!prompt) return res.status(400).json({ error: 'prompt is required' });
334	  const entry = {
335	    id: id || genId(),
336	    agent: agent || '',
337	    agentName: agentName || 'Unknown',
338	    prompt,
339	    output: (output || '').slice(0, 500000),
340	    duration: duration || 0,
341	    status: status || 'success',
342	    timestamp: timestamp || new Date().toISOString(),
343	  };
344	  const list = loadPlaygroundHistory();
345	  list.unshift(entry);
346	  savePlaygroundHistory(list);
347	  res.json(entry);
348	});
349	
350	// DELETE /api/playground/history/:id
351	router.delete('/playground/history/:id', rateLimit('write'), (req, res) => {
352	  const list = loadPlaygroundHistory().filter(h => h.id !== req.params.id);
353	  savePlaygroundHistory(list);
354	  res.json({ ok: true });
355	});
356	
357	// DELETE /api/playground/history
358	router.delete('/playground/history', rateLimit('write'), (req, res) => {
359	  savePlaygroundHistory([]);
360	  res.json({ ok: true });
361	});
362	
363	module.exports = router;
