3	const express = require('express');
4	const router = express.Router();
5	const fs = require('fs');
6	const path = require('path');
7	const os = require('os');
8	
9	const tasks = require('../lib/tasks');
10	const db = require('../db');
11	
12	const REGISTRY_PATH = path.join(os.homedir(), '.claude', 'org', 'registry.json');
13	
14	// Cost tier penalty for the dispatch scoring formula. Loaded from
15	// model_routing.json so it stays in sync with the policy file.
16	function tierCostPenalty(model) {
17	  if (!model) return 0.5;
18	  const m = String(model).toLowerCase();
19	  if (m.includes('opus')) return 1.0;
20	  if (m.includes('haiku')) return 0.05;
21	  if (m.includes('sonnet')) return 0.3;
22	  return 0.5;
23	}
24	
25	function priorityBoost(priority) {
26	  switch (priority) {
27	    case 'p0': return 0.3;
28	    case 'p1': return 0.15;
29	    case 'p2': return 0;
30	    case 'p3': return -0.05;
31	    default: return 0;
32	  }
33	}
34	
35	// Score formula:
36	//   skillScore * 0.5      ← skill match (0-1)
37	// + (1 - loadPct) * 0.2   ← favor less-loaded agents
38	// + successRate * 0.2     ← favor proven performers
39	// - costPenalty * costWeight ← break ties toward cheap agents (default 0.1)
40	// + priorityBoost         ← P0 lifts up, P3 nudges down
41	//
42	// `costWeight` is dynamic: when monthly burn > threshold and the task isn't
43	// in the exempt list, we crank cost penalty up to 0.45 so cheap (haiku) tier
44	// dominates. This implements model_routing.json's `downgrade_fast_to_cheap_
45	// for_non_critical` rule.
46	function rankCandidate(c, opts = {}) {
47	  const skill = c.skillScore || 0;
48	  const loadPct = c.maxConcurrentTasks > 0
49	    ? Math.min(1, (c.activeTaskCount || 0) / c.maxConcurrentTasks)
50	    : 1;
51	  const sr = typeof c.successRate === 'number' ? c.successRate : 0.7;
52	  const cost = tierCostPenalty(c.model);
53	  const costWeight = typeof opts.costWeight === 'number' ? opts.costWeight : 0.1;
54	
55	  const score =
56	      skill * 0.5
57	    + (1 - loadPct) * 0.2
58	    + sr * 0.2
59	    - cost * costWeight
60	    + priorityBoost(opts.priority);
61	
62	  return Math.max(0, score);
63	}
64	
65	// Compute budget context for a dispatch. Returns:
66	//   { overBudget: boolean, burnPct: number|null, costWeight: number,
67	//     downgrade: boolean, exemptTask: boolean }
68	//
69	// downgrade=true means we're past the 110% threshold AND the task isn't in
70	// the exempt list. costWeight gets cranked up to bias toward cheap tier.
71	function computeBudgetContext(taskType) {
72	  try {
73	    const policy = db.loadModelRouting() || {};
74	    const rules = policy.downgradeRules || [];
75	    const downgradeRule = rules.find((r) => r.trigger === 'monthly_burn_above_pct');
76	    if (!downgradeRule) return { overBudget: false, burnPct: null, costWeight: 0.1, downgrade: false, exemptTask: false };
77	
78	    // Compute current burn pct from last 30d agent_runs
79	    const cutoffMs = Date.now() - 30 * 24 * 3600 * 1000;
80	    const cutoffIso = new Date(cutoffMs).toISOString();
81	    const runs = db.getRecentAgentRuns(30 * 24);
82	    const totalCost = runs.reduce((acc, r) => {
83	      if (r.timestamp < cutoffIso) return acc;
84	      return acc + (r.estimatedCost || 0);
85	    }, 0);
86	    const totalBudget = policy.totalMonthlyBudgetUsd || 0;
87	    if (totalBudget <= 0) return { overBudget: false, burnPct: null, costWeight: 0.1, downgrade: false, exemptTask: false };
88	
89	    const burnPct = (totalCost / totalBudget) * 100;
90	    const overBudget = burnPct > (downgradeRule.threshold || 110);
91	    const exemptTasks = downgradeRule.exempt_tasks || [];
92	    const exemptTask = !!taskType && exemptTasks.includes(taskType);
93	    const downgrade = overBudget && !exemptTask;
94	
95	    return {
96	      overBudget,
97	      burnPct: Math.round(burnPct * 10) / 10,
98	      costWeight: downgrade ? 0.45 : 0.1,
99	      downgrade,
100	      exemptTask,
101	    };
102	  } catch (err) {
103	    console.warn('[dispatch] computeBudgetContext failed:', err.message);
104	    return { overBudget: false, burnPct: null, costWeight: 0.1, downgrade: false, exemptTask: false };
105	  }
106	}
107	
108	// Read registry fresh every call. Avoids Node's require() cache (which can hold
109	// stale data) AND avoids mid-write JSON.parse failures by catching + falling back.
110	function loadRegistry() {
111	  try {
112	    const raw = fs.readFileSync(REGISTRY_PATH, 'utf-8');
113	    return JSON.parse(raw);
114	  } catch (err) {
115	    // File missing OR mid-write JSON.parse failure → safe fallback.
116	    return { agents: {} };
117	  }
118	}
119	
120	function tokenize(text) {
121	  return text
122	    .toLowerCase()
123	    .replace(/[^a-z0-9\s]/g, ' ')
124	    .split(/\s+/)
125	    .filter(t => t.length > 2);
126	}
127	
128	/**
129	 * GET /api/dispatch/recommend?q=<free text>
130	 * Returns top agents ranked by skill overlap with the query.
131	 */
132	router.get('/dispatch/recommend', (req, res) => {
133	  const q = (req.query.q || '').trim();
134	  if (!q) return res.status(400).json({ error: 'q is required' });
135	
136	  const tokens = tokenize(q);
137	  if (tokens.length === 0) return res.json({ results: [] });
138	
139	  const registry = loadRegistry();
140	  const agents = registry.agents || {};
141	
142	  const scored = [];
143	
144	  for (const [id, agent] of Object.entries(agents)) {
145	    if (agent.status === 'retired') continue;
146	
147	    const skills = agent.skills || {};
148	    let rawScore = 0;
149	    const matchedSkills = [];
150	
151	    for (const token of tokens) {
152	      for (const [skillKey, skillData] of Object.entries(skills)) {
153	        // exact or substring match against skill key
154	        if (skillKey === token || skillKey.includes(token) || token.includes(skillKey)) {
155	          const contribution = (skillData.score || 0) * Math.log1p(skillData.hits || 0);
156	          rawScore += contribution;
157	          if (!matchedSkills.includes(skillKey)) matchedSkills.push(skillKey);
158	        }
159	      }
160	    }
161	
162	    if (rawScore > 0) {
163	      scored.push({
164	        agentId: id,
165	        name: agent.title ? `${id} — ${agent.title}` : id,
166	        department: agent.department || null,
167	        level: agent.levelTitle || null,
