201	const VALID_TASK_TYPES = new Set(['build', 'bug', 'spike', 'review', 'design', 'research', 'deploy', 'test', 'workflow', 'general']);
202	const VALID_PRIORITIES = new Set(['p0', 'p1', 'p2', 'p3']);
203	const MAX_QUERY_LEN = 2000;
204	const MAX_TITLE_LEN = 200;
205	const MAX_EST_TOKENS = 2_000_000;
206	
207	router.post('/dispatch/assign', (req, res) => {
208	  const { query, taskType, priority = 'p2', estimatedTokens = 0,
209	    preferredAgent, dryRun = false, title } = req.body || {};
210	
211	  // ── Input validation ──────────────────────────────────────────────────
212	  if (!query || typeof query !== 'string') {
213	    return res.status(400).json({ error: 'query is required (string)' });
214	  }
215	  if (query.length > MAX_QUERY_LEN) {
216	    return res.status(400).json({ error: `query too long (max ${MAX_QUERY_LEN} chars)` });
217	  }
218	  if (taskType && !VALID_TASK_TYPES.has(taskType)) {
219	    return res.status(400).json({
220	      error: `invalid taskType "${taskType}"`,
221	      valid: Array.from(VALID_TASK_TYPES),
222	    });
223	  }
224	  if (!VALID_PRIORITIES.has(priority)) {
225	    return res.status(400).json({
226	      error: `invalid priority "${priority}"`,
227	      valid: Array.from(VALID_PRIORITIES),
228	    });
229	  }
230	  if (typeof estimatedTokens !== 'number' || estimatedTokens < 0 || estimatedTokens > MAX_EST_TOKENS) {
231	    return res.status(400).json({ error: `estimatedTokens must be a number 0..${MAX_EST_TOKENS}` });
232	  }
233	  if (preferredAgent && (typeof preferredAgent !== 'string' || preferredAgent.length > 100)) {
234	    return res.status(400).json({ error: 'preferredAgent must be a short string id' });
235	  }
236	  if (title && (typeof title !== 'string' || title.length > MAX_TITLE_LEN)) {
237	    return res.status(400).json({ error: `title must be a string ≤ ${MAX_TITLE_LEN} chars` });
238	  }
239	
240	  const tokens = tokenize(query);
241	  if (tokens.length === 0) {
242	    return res.status(400).json({ error: 'query produced no usable tokens' });
243	  }
244	
245	  // 1. Build candidate set — same skill scoring as /recommend, top-10
246	  const registry = loadRegistry();
247	  const agentEntries = Object.entries(registry.agents || {});
248	  const skillRanked = [];
249	  for (const [id, agent] of agentEntries) {
250	    if (agent.status === 'retired') continue;
251	    const skills = agent.skills || {};
252	    let rawScore = 0;
253	    const matchedSkills = [];
254	    for (const token of tokens) {
255	      for (const [skillKey, skillData] of Object.entries(skills)) {
256	        if (skillKey === token || skillKey.includes(token) || token.includes(skillKey)) {
257	          rawScore += (skillData.score || 0) * Math.log1p(skillData.hits || 0);
258	          if (!matchedSkills.includes(skillKey)) matchedSkills.push(skillKey);
259	        }
260	      }
261	    }
262	    if (rawScore > 0) {
263	      skillRanked.push({ id, agent, rawScore, matchedSkills });
264	    }
265	  }
266	
267	  if (skillRanked.length === 0) {
268	    return res.status(404).json({ error: 'no agents matched the query', tokens });
269	  }
270	
271	  // Normalize skill scores to 0-1
272	  const maxRaw = skillRanked.reduce((m, c) => Math.max(m, c.rawScore), 1);
273	  for (const c of skillRanked) c.skillScore = c.rawScore / maxRaw;
274	
275	  // 2. Hydrate with live load + perf signals + cost tier
276	  const loads = tasks.getAllAgentLoad();
277	  const candidates = skillRanked
278	    .map((c) => {
279	      const load = loads[c.id] || { activeTaskCount: 0, maxConcurrentTasks: 3, loadStatus: 'free' };
280	      const stats = c.agent.stats || {};
