283	        title: c.agent.title || null,
284	        department: c.agent.department || null,
285	        tier: c.agent.tier || null,
286	        status: c.agent.status || 'active',
287	        model: c.agent.model || 'sonnet',
288	        skillScore: Math.round(c.skillScore * 100) / 100,
289	        matchedSkills: c.matchedSkills,
