320	
321	  // 5. preferredAgent override (only if eligible)
322	  let chosen = null;
323	  if (preferredAgent) {
324	    chosen = eligible.find((c) => c.agentId === preferredAgent) || null;
325	  }
326	  if (!chosen) chosen = eligible[0] || null;
327	
328	  if (!chosen) {
329	    return res.status(429).json({
