339	      dryRun: true,
340	      query,
341	      tokens,
342	      chosen: chosen.agentId,
343	      score: chosen.score,
344	      budget,
345	      candidates: eligible.slice(0, 5),
346	    });
347	  }
348	
349	  // 6. Create the task — increments agent load via tasks.createTask
350	  let task;
351	  try {
352	    task = tasks.createTask({
353	      agentId: chosen.agentId,
354	      source: 'auto-route',
355	      taskType: taskType || 'general',
356	      title: title || query.slice(0, 80),
357	      prompt: query,
358	      priority,
359	      estimatedTokens,
360	      metadata: {
361	        dispatcher: 'POST /api/dispatch/assign',
362	        score: chosen.score,
363	        skillScore: chosen.skillScore,
364	        matchedSkills: chosen.matchedSkills,
365	        loadAtAssignment: { active: chosen.activeTaskCount, max: chosen.maxConcurrentTasks },
366	      },
367	    });
368	  } catch (err) {
369	    return res.status(500).json({ error: err.message });
370	  }
371	
372	  res.json({
373	    ok: true,
374	    taskId: task.id,
375	    agentId: chosen.agentId,
376	    score: chosen.score,
377	    reason: explainScore(chosen, { priority, budget }),
378	    budget,
379	    candidates: eligible.slice(0, 5),
380	  });
381	});
