383	function explainScore(c, opts) {
384	  const parts = [];
385	  parts.push(`skill=${c.skillScore.toFixed(2)}`);
386	  parts.push(`load=${c.activeTaskCount}/${c.maxConcurrentTasks}`);
387	  if (typeof c.successRate === 'number') parts.push(`success=${c.successRate.toFixed(2)}`);
388	  parts.push(`tier=${c.model}`);
389	  if (opts.priority && opts.priority !== 'p2') parts.push(`priority=${opts.priority}`);
390	  if (opts.budget?.downgrade) parts.push(`budget-downgrade(burn=${opts.budget.burnPct}%)`);
391	  return parts.join(' · ');
392	}
